// 冷恢复按实际Common顺序逐人扩展谱系；后来出生的人不倒填先前人物的亲代或禀赋。
#include "family_birth_lineage.hpp"
#include <algorithm>
#include <charconv>
#include <map>
#include <set>
namespace hanmo::resident {namespace {
// 出生不会采用作者原ID；新人物必须是原实例分配器产生的唯一actor号。
bool actor_id(const CommonStore& c,const StableId& id){const StableId prefix="actor:";if(id.rfind(prefix,0)!=0)return false;const auto raw=id.substr(prefix.size());Integer number=0;auto r=std::from_chars(raw.data(),raw.data()+raw.size(),number);return r.ec==std::errc{}&&r.ptr==raw.data()+raw.size()&&number>0&&number<c.state().next_instance_id&&raw==std::to_string(number);}
// 未知父母/未知档位保持未知；不能从当前后天技艺补一个先天0档。
InnateParentSource parent(const BirthLineageProjection& p,const StableId& actor,const StableId& family){InnateParentSource out;out.actor_id=actor;if(const auto* levels=p.innate_levels.find(actor))if(const auto* level=levels->find(family))out.level=*level;return out;}
// 查询祖先用有限已核图，父母缺项就停止，不产生无血缘证明。
std::set<StableId> ancestors(const BirthLineageProjection& p,const StableId& who){std::set<StableId> result;std::vector<StableId> pending{who};while(!pending.empty()){auto actor=std::move(pending.back());pending.pop_back();if(const auto* origin=p.origins.find(actor))for(const auto& id:origin->parent_actor_ids)if(result.insert(id).second)pending.push_back(id);}return result;}
}
Outcome<BirthLineageProjection> read_birth_lineage_projection(const CommonStore& c,const CommonCatalog& common,const FamilyLineageCatalog& catalog,const FamilyBirthState& births){auto fail=[](const StableId& code,const StableId& id=StableId{})->Outcome<BirthLineageProjection>{return {false,{},common_failure(code,id).error};};auto valid=validate_family_lineage_catalog(c,common,catalog);if(!valid.ok)return {false,{},valid.error};if(!catalog.enabled)return fail("FamilyLineageProfileRequired");if(births.births.size()>65536)return fail("BirthLineageLimit");BirthLineageProjection out;out.origins=catalog.origins;out.innate_levels=catalog.original_innate_levels;std::set<StableId> seen,known(common.actor_ids.begin(),common.actor_ids.end()),created;
 for(const auto& row:c.state().facts.rows()){
  const auto* birth=births.births.find(row.first);if(!birth){if(row.second.domain=="family_birth"&&row.second.kind=="family_birth_recorded")return fail("MissingBiologicalBirthPayload",row.first);if(row.second.domain=="family_birth"&&row.second.kind=="actor_creation"){const auto* source=out.birth_sources.find(row.first);if(!source||!seen.count(*source)||!created.insert(row.first).second)return fail("BiologicalCreationSourceOrder",row.first);}seen.insert(row.first);continue;}
  if(row.second.domain!="family_birth"||row.second.kind!="family_birth_recorded"||row.second.id!=row.first||birth->kind!=row.second.kind)return fail("BiologicalBirthHeaderMismatch",row.first);const auto* accepted=births.replies.find(birth->accepted_id);const auto* accept_head=c.state().facts.find(birth->accepted_id);if(!accepted||accepted->decision!="accepted"||accepted->kind!="family_birth_accepted"||!accepted->confirmation||!accept_head||accept_head->kind!=accepted->kind||accept_head->domain!="family_birth"||!seen.count(birth->accepted_id))return fail("BiologicalBirthAcceptanceRequired",row.first);const auto& from=*accepted->confirmation;const std::vector<StableId> expected{from.speaker_actor_id,from.listener_actor_id};if(birth->biological_parent_ids!=expected||birth->prototype_id!=from.terms.child_prototype_id||birth->place_id!=from.terms.place_id||birth->tick<accepted->due_tick||birth->tick>c.tick()||birth->revision<accepted->revision||birth->revision>c.revision())return fail("BiologicalBirthTermsMismatch",row.first);
  for(const auto& id:expected){const auto* person=c.state().actors.find(id);if(!known.count(id)||!person||!person->birth_tick||*person->birth_tick>birth->tick-18*720)return fail("BiologicalParentIdentityUnavailable",id);}
  if(!actor_id(c,birth->actor_id)||known.count(birth->actor_id)||!common.places.find(birth->place_id)||birth->display_name.empty()||birth->display_name.size()>256)return fail("BiologicalChildIdentityMismatch",row.first);const auto* person=c.state().actors.find(birth->actor_id);if(!person||person->id!=birth->actor_id||person->birth_tick!=birth->tick||person->created_tick!=birth->tick||person->prototype_id!=birth->prototype_id||person->display_name!=birth->display_name||person->wallet_id!="personal:"+birth->actor_id||person->inventory_id!="bag:"+birth->actor_id)return fail("BiologicalChildIdentityMismatch",row.first);
  if(birth->innate.size()!=catalog.endowment.families.size())return fail("BirthInnateFamilySetMismatch",row.first);OrderedTable<Integer> levels;for(const auto& family:catalog.endowment.families.rows()){const auto* result=birth->innate.find(family.first);if(!result||result->family_id!=family.first)return fail("BirthInnateFamilySetMismatch",row.first);const auto first=parent(out,expected[0],family.first),second=parent(out,expected[1],family.first);if(result->first.actor_id!=first.actor_id||result->first.level!=first.level||result->second.actor_id!=second.actor_id||result->second.level!=second.level)return fail("BirthInnateParentSnapshotMismatch",row.first);valid=validate_birth_innate_result(catalog.endowment,*result);if(!valid.ok)return {false,{},valid.error};levels.insert(family.first,result->level);}
  out.origins.insert(birth->actor_id,{birth->actor_id,expected});out.innate_levels.insert(birth->actor_id,std::move(levels));out.birth_sources.insert(birth->actor_id,row.first);known.insert(birth->actor_id);seen.insert(row.first);
 }
 if(out.birth_sources.size()!=births.births.size()||created.size()!=births.births.size())return fail("BiologicalCreationPayloadMismatch");return {true,std::move(out),{}};
}
Outcome<BiologicalRelationRead> read_birth_biological_relation(const CommonStore& c,const CommonCatalog& common,const FamilyLineageCatalog& catalog,const FamilyBirthState& births,const StableId& first,const StableId& second){auto projection=read_birth_lineage_projection(c,common,catalog,births);if(!projection.ok)return {false,{},projection.error};auto known=[&](const StableId& id){return c.actor(id)&&(projection.value.birth_sources.find(id)||std::find(common.actor_ids.begin(),common.actor_ids.end(),id)!=common.actor_ids.end());};if(first==second||!known(first)||!known(second))return {false,{},common_failure("BiologicalRelationUnavailable").error};const auto& p=projection.value;const auto a=ancestors(p,first),b=ancestors(p,second);BiologicalRelationRead out;out.source_identity=c.state().identity;out.first_actor_id=first;out.second_actor_id=second;out.known_direct_line=a.count(second)||b.count(first);const auto* x=p.origins.find(first);const auto* y=p.origins.find(second);out.first_parents_complete=x&&x->parent_actor_ids.size()==2;out.second_parents_complete=y&&y->parent_actor_ids.size()==2;if(x&&y)for(const auto& id:x->parent_actor_ids)if(std::find(y->parent_actor_ids.begin(),y->parent_actor_ids.end(),id)!=y->parent_actor_ids.end())out.common_parent_actor_ids.push_back(id);out.known_siblings=!out.common_parent_actor_ids.empty();return {true,std::move(out),{}};}
Outcome<InnateParentSource> read_birth_innate_parent(const CommonStore& c,const CommonCatalog& common,const FamilyLineageCatalog& catalog,const FamilyBirthState& births,const StableId& actor,const StableId& family){auto p=read_birth_lineage_projection(c,common,catalog,births);if(!p.ok)return {false,{},p.error};if(!catalog.endowment.families.find(family)||!c.actor(actor)||(!p.value.birth_sources.find(actor)&&std::find(common.actor_ids.begin(),common.actor_ids.end(),actor)==common.actor_ids.end()))return {false,{},common_failure("InnateParentSourceUnavailable").error};return {true,parent(p.value,actor,family),{}};}
}
